INSERT INTO public.knowledge_segment_vector (id, segment_id, knowledge_base_id, document_id, content, embedding, create_time, update_time) VALUES (10, 10, 1, 1, '日志，确认服务端口正常监听且数据库连接成功。
第四步构建前端项目，配置后端接口地址并生成静态资源。
第五步访问系统登录页，使用管理员账号登录后台，检查用户管理、知识库管理、文档管理等页面是否正常。
七、验收标准
管理员可以正常登录系统，知识库管理页面可以创建和查询知识库，知识文档管理页面可以上传文件并保存文件地址。
文件下载地址可以正常访问，后端日志没有数据库连接异常，页面刷新后路由访问正常。
八、常见问题
页面可以打开但接口请求失败时，需要检查前端接口地址、后端服务状态和跨域配置。
文件上传成功但无法下载时，需要检查 fileBaseUrl 配置和 files 目录是否存在对应文件。
PGVector 无法使用时，需要确认 PostgreSQL 已安装 pgvector 扩展，并在数据库中启用扩展。', '[-0.059529908,0.06245707,-0.028992051,0.027709363,-0.024963094,-0.042262945,0.007293236,0.08051338,-0.022019489,0.089722425,0.06686426,0.016790066,-0.040289577,-0.0015509432,-0.051307544,0.049103953,0.0048717503,-0.048314605,0.0009753778,-0.018697653,-0.0072603463,-0.04091448,0.0050649755,-0.046637245,0.015458043,0.020555908,0.0017051125,-0.02964984,0.033843245,0.010911075,0.029156499,-0.028959163,0.016444726,-0.031064088,-0.015153815,0.019914564,-0.020407906,0.051833775,0.016296724,-0.0093981605,-0.018993659,0.019618558,-0.02585111,-0.0057597654,-0.01868121,0.008168918,-0.05995747,-0.044663876,-0.017184738,0.045354553,-0.000104385465,-0.021756373,-0.024403973,0.01429869,-0.031129867,-0.0020720356,0.049005285,0.035849504,0.011470197,0.009225491,0.02251283,0.03723086,-0.005459649,0.0010257398,-0.011618199,0.0050855316,0.0017349186,-0.0017390298,-0.0038603994,-0.034402367,0.018483872,0.006380554,0.04255895,0.027890256,-0.039829127,0.07104122,-0.004892306,-0.0069150073,0.01774386,-0.03219877,0.025587995,0.02254572,0.02404219,-0.0017020291,0.0077577997,0.055451617,-0.0138300145,0.087354384,0.020407906,0.08794639,0.06900207,0.010894631,-0.01861543,0.026985796,-0.006413443,-0.11932293,-0.03598106,-0.0024728756,0.03155743,0.03854644,-0.024354639,0.07557996,-0.026640456,-0.061470386,-0.0036445623,-0.005282868,-0.02946895,-0.03719797,-0.021082139,0.055648953,-0.025275543,-0.023581738,-0.003110109,-0.005780321,0.02585111,-0.0011161858,-0.013353118,-0.005661097,-0.009825724,0.009661277,-0.037954427,0.044532318,-0.02887694,-0.015129148,0.034270808,0.013386007,0.052557345,-0.028104037,0.046637245,-0.00041522933,0.0074659055,-0.023894187,-0.01702029,-0.041506488,-0.008567702,-0.022118157,0.040651362,0.012407546,-0.049071062,-0.025291989,-0.018960768,-0.04505855,0.06880473,0.05591207,-0.022003043,-0.007478239,-0.0115030855,-0.030159628,0.008888374,0.015606045,-0.011165969,0.0044729654,-0.035652164,0.017809639,-0.0346983