INSERT INTO public.knowledge_segment_vector (id, segment_id, knowledge_base_id, document_id, content, embedding, create_time, update_time) VALUES (34, 31, 2, 2, '售后退款流程

一、文档目的

本文档用于规范客户退款、退订、售后咨询和工单处理流程。客服、售后、财务和运营人员需要按照本文档处理客户退款申请，确保退款处理及时、记录完整、责任清晰。

二、适用范围

本文档适用于客户购买产品后申请退款、客户因服务不可用申请退订、客户重复付款需要退回多付金额、客户对订单金额或发票合同存在疑问等场景。

三、退款受理原则

客服收到退款申请后，需要先核实订单是否真实存在，包括订单号、客户账号、付款时间、付款金额和购买产品。退款原因需要记录在工单中，常见原因包括误购买、重复付款、服务未开通、功能不符合预期、合同条款约定可以退款、售后协商退款。

四、退款处理流程

客户可以通过在线客服、电话、邮件或工单系统提交退款申请。客服需要引导客户提供客户账号、订单号、付款时间、付款金额、退款原因、收款账户信息和发票情况。

客服收到申请后，需要在系统中创建售后工单。工单标题建议格式为：退款申请-客户名称-订单号。工单内容需要包含客户申请信息、订单核验结果和初步处理意见。', '[-0.022617938,-0.03785562,0.0403051,0.0054795216,0.05150273,-0.071321264,0.02443119,0.0903445,-0.00870043,0.05242526,-0.010012653,0.05901023,-0.01606478,0.033338394,-0.006537252,0.024749305,0.079719484,-0.081691794,-0.06839461,0.012247407,0.05019846,0.045935728,0.018943716,0.052075338,0.042977262,0.05675162,-0.030316308,-0.06635868,0.040527783,0.012851824,0.029361965,-0.061523337,-0.003479377,-0.008294835,0.039096266,0.03763294,-0.0060083866,-0.0050063264,0.008469798,-0.026021762,0.0029584644,0.011961103,0.04332719,0.054683875,0.020136645,0.018530168,0.04358168,-0.083791345,-0.03610599,0.018371109,-0.012430322,-0.02287243,0.010211474,-0.007646676,0.010911326,0.041704804,0.016939595,0.00097024906,0.015651232,-0.010799985,0.004672306,0.038746342,0.020391136,-0.005511333,-0.024224415,-0.02901204,0.007925026,-0.021918086,0.025926327,-0.03343383,0.022538409,0.0137982145,-0.009121932,0.025417345,-0.014307198,0.037791997,0.008517515,0.018243864,0.0120803965,0.0069746594,0.0028033836,-0.01762354,-0.0211228,0.0411322,0.058692116,-0.014887757,0.0216795,0.025703648,0.03286122,0.063654706,0.008867441,-0.0076188412,0.010887467,-0.0027357843,-0.007746087,-0.0086288545,0.022363447,0.031827353,-0.009861548,0.026832955,-0.05608358,0.05302968,0.0011173771,-0.019898059,0.009320754,0.08016484,-0.020947836,0.0109192785,-0.009042404,1.5354304e-05,-0.029123379,-0.021027366,0.007117811,-0.022395257,0.031079782,-0.054906555,0.039128076,0.009575245,0.008151683,0.010275097,0.007917074,0.03230452,-0.03394281,-0.03476991,0.019579945,-0.018180242,0.025687743,-0.034642663,0.014919568,-0.05675162,-0.038714528,-0.010632976,-0.016541952,-0.017162275,0.018864186,0.044790514,-0.0059328345,0.010585259,-0.021075083,-0.0327976,0.06737664,-0.040877707,0.034356363,0.013670969,-0.05894661,-0.045267686,-0.04428153,0.021218235,-0.028646206,-0.004135488,-0.03282941,-0.032893036,-0.024542531,0.039032646,-0.0007580071,0.010378484,0.017