INSERT INTO public.knowledge_segment_vector (id, segment_id, knowledge_base_id, document_id, content, embedding, create_time, update_time) VALUES (36, 33, 2, 2, '客户重复付款时，客服需要核对两笔支付流水。如果确认重复付款，一般退回重复支付金额。客户已经使用服务时，需要根据合同条款判断是否支持部分退款。合同客户退款需要同时核验合同条款、付款凭证和服务交付记录。

八、客服回复示例

您好，已收到您的退款申请。我们会先核验订单状态、付款记录和发票情况。审核通过后，退款会按原支付方式或约定账户退回。一般到账时间为 1 到 7 个工作日，具体以银行或支付渠道处理时间为准。

九、工单关闭标准

